60	public class ArchivedTimelineLoaderV1 implements ArchivedTimelineLoader {
61	  private static final String MERGE_ARCHIVE_PLAN_NAME = "mergeArchivePlan";
62	  private static final Pattern ARCHIVE_FILE_PATTERN =
63	      Pattern.compile("^\\.commits_\\.archive\\.([0-9]+).*");
64	  private static final String STATE_TRANSITION_TIME = "stateTransitionTime";
65	  private static final String ACTION_TYPE_KEY = "actionType";
66	  private static final Logger LOG = LoggerFactory.getLogger(ArchivedTimelineLoaderV1.class);
67	
68	  @Override
69	  public void loadInstants(HoodieTableMetaClient metaClient,
70	                                          @Nullable HoodieArchivedTimeline.TimeRangeFilter filter,
71	                                          HoodieArchivedTimeline.LoadMode loadMode,
72	                                          Function<GenericRecord, Boolean> commitsFilter,
73	                                          BiConsumer<String, GenericRecord> recordConsumer) {
74	    Set<String> instantsInRange = new HashSet<>();
75	    try {
76	      // List all files
77	      List<StoragePathInfo> entryList = metaClient.getStorage().globEntries(
78	          new StoragePath(metaClient.getArchivePath(), ".commits_.archive*"));
79	
80	      // Sort files by version suffix in reverse (implies reverse chronological order)
81	      entryList.sort(new ArchiveFileVersionComparator());
82	
83	      for (StoragePathInfo fs : entryList) {
84	        // Read the archived file
85	        try (HoodieLogFormat.Reader reader = HoodieLogFormat.newReader(metaClient.getStorage(),
86	            new HoodieLogFile(fs.getPath()), HoodieArchivedMetaEntry.getClassSchema())) {
87	          int instantsInPreviousFile = instantsInRange.size();
88	          // Read the avro blocks
89	          while (reader.hasNext()) {
90	            HoodieLogBlock block = reader.next();
91	            if (block instanceof HoodieAvroDataBlock) {
92	              HoodieAvroDataBlock avroBlock = (HoodieAvroDataBlock) block;
93	              // TODO If we can store additional metadata in datablock, we can skip parsing records
94	              // (such as startTime, endTime of records in the block)
95	              try (ClosableIterator<HoodieRecord<IndexedRecord>> itr = avroBlock.getRecordIterator(HoodieRecord.HoodieRecordType.AVRO)) {
96	                StreamSupport.stream(Spliterators.spliteratorUnknownSize(itr, Spliterator.IMMUTABLE), true)
97	                    // Filter blocks in desired time window
98	                    .map(r -> (GenericRecord) r.getData())
99	                    .filter(commitsFilter::apply)
100	                    .forEach(r -> {
101	                      String instantTime = r.get(HoodieTableMetaClient.COMMIT_TIME_KEY).toString();
102	                      instantsInRange.add(instantTime);
103	                      recordConsumer.accept(instantTime, r);
104	                    });
105	              }
106	            }
107	          }
108	
109	          if (filter != null) {
110	            int instantsInCurrentFile = instantsInRange.size() - instantsInPreviousFile;
111	            if (instantsInPreviousFile > 0 && instantsInCurrentFile == 0) {
112	              // Note that this is an optimization to skip reading unnecessary archived files
113	              // This signals we crossed lower bound of desired time window.
114	              break;
115	            }
116	          }
117	        } catch (Exception originalException) {
118	          // merge small archive files may left uncompleted archive file which will cause exception.
119	          // need to ignore this kind of exception here.
120	          try {
121	            StoragePath planPath = new StoragePath(metaClient.getArchivePath(), MERGE_ARCHIVE_PLAN_NAME);
122	            HoodieStorage storage = metaClient.getStorage();
123	            if (storage.exists(planPath)) {
124	              HoodieMergeArchiveFilePlan plan = TimelineMetadataUtils.deserializeAvroMetadata(FileIOUtils.readDataFromPath(storage, planPath).get(), HoodieMergeArchiveFilePlan.class);
125	              String mergedArchiveFileName = plan.getMergedArchiveFileName();
126	              if (!StringUtils.isNullOrEmpty(mergedArchiveFileName) && fs.getPath().getName().equalsIgnoreCase(mergedArchiveFileName)) {
127	                LOG.warn("Catch exception because of reading uncompleted merging archive file " + mergedArchiveFileName + ". Ignore it here.");
128	                continue;
129	              }
130	            }
131	            throw originalException;
132	          } catch (Exception e) {
133	            // If anything wrong during parsing merge archive plan, we need to throw the original exception.
134	            // For example corrupted archive file and corrupted plan are both existed.
135	            throw originalException;
136	          }
137	        }
138	      }
139	    } catch (IOException e) {
140	      throw new HoodieIOException(
141	          "Could not load archived commit timeline from path " + metaClient.getArchivePath(), e);
142	    }
143	  }
